import{_ as s,c as t,o as a,ag as o}from"./chunks/framework.B-XtCDNB.js";const n="/screenshots/payments-gateways.png",i="/screenshots/payments-alternative.png",r="/screenshots/payments-order-flow.png",c="/screenshots/payments-tax.png",l="/features/feat-invoices.png",y=JSON.parse('{"title":"Payments","description":"Meloncart supports multiple payment methods out of the box, so you can offer customers the checkout experience that works best for your business.","frontmatter":{"title":"Payments","description":"Meloncart supports multiple payment methods out of the box, so you can offer customers the checkout experience that works best for your business.","layout":"doc","aside":false},"headers":[],"relativePath":"features/payments.md","filePath":"features/payments.md"}'),d={name:"features/payments.md"};function p(m,e,u,v,h,g){return a(),t("div",null,[...e[0]||(e[0]=[o('<div class="mc-features-page"><div class="mc-features-hero"><h1>Payments</h1><p>Meloncart supports multiple payment methods out of the box, so you can offer customers the <strong>checkout experience</strong> that works best for your business.</p></div><div class="mc-detail-body"><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Payment Gateways</h2><p>Stripe, <strong>PayPal</strong> and <strong>RazorPay</strong> are included as built-in gateways, covering the vast majority of online transactions worldwide. All support the full payment lifecycle, including authorization, capture, <strong>refunds</strong> and voids, all manageable from the order screen.</p><p>Additional gateways can be added through the Marketplace or by building your own using Meloncart&#39;s <strong>payment gateway API</strong>.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+n+'" alt="Payment gateways"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Alternative Payment Methods</h2><p>Not every transaction goes through a card processor. Meloncart lets you configure custom payment methods for scenarios like:</p><ul><li><strong>Cash on delivery</strong> to collect payment when the order arrives</li><li><strong>Bank transfer</strong> with account details and manual reconciliation</li><li><strong>Purchase orders / NET terms</strong> for B2B and wholesale billing workflows</li><li><strong>Check or money order</strong> for offline payments with manual confirmation</li></ul><p>Each method can be restricted to specific <strong>customer groups</strong>, so you can offer NET30 terms to wholesale accounts without exposing them to retail customers.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+i+'" alt="Alternative payment methods"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Configurable Order Flow</h2><p>Define how orders move through your fulfillment process with configurable <strong>status routes</strong>. Set the initial status when an order is placed, then map out the transitions that match your workflow, for example: Pending, Processing, Shipped, Completed.</p><p>Each status transition can trigger automatic <strong>actions</strong> like customer email notifications, and you can restrict which backend users see orders at each stage.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+r+'" alt="Configurable order flow"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Tax Calculation</h2><p>Meloncart handles <strong>tax automatically</strong> based on the customer&#39;s location. Both tax-inclusive and tax-exclusive pricing models are supported so you can match your region&#39;s conventions.</p><p>Multiple tax classes let you apply different rates to different product types (standard, reduced or zero-rated) and tax-exempt customer groups ensure B2B transactions are handled correctly.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+c+'" alt="Tax calculation"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Invoices</h2><p>Professional invoices are generated automatically with each order, branded with your company logo, registration <strong>numbers</strong> and contact details. Invoices support full and partial payment tracking, and update automatically when orders are edited.</p></div><div class="mc-detail-section__visual"><img src="'+l+'" alt="Invoices"></div></div></div></div>',1)])])}const f=s(d,[["render",p]]);export{y as __pageData,f as default};
